import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const c=JSON.parse('{"title":"业务删除与对象回收","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/deletion-cleanup","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/deletion-cleanup.md","filePath":"tutorials/deletion-cleanup.md"}'),n={name:"tutorials/deletion-cleanup.md"};function l(r,a,p,h,o,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="业务删除与对象回收" tabindex="-1">业务删除与对象回收 <a class="header-anchor" href="#业务删除与对象回收" aria-label="Permalink to &quot;业务删除与对象回收&quot;">​</a></h1><p>目标：删除自己的资源后立即停止授权访问，再用持久任务可靠清理字节。前提是已接入 <a href="./attachments">Files</a> 和 <a href="./document-exports">Jobs</a>。删除是持久数据变更，知识库参考没有回收站。</p><h2 id="先提交不可见性" tabindex="-1">先提交不可见性 <a class="header-anchor" href="#先提交不可见性" aria-label="Permalink to &quot;先提交不可见性&quot;">​</a></h2><p>Knowledge 删除用例短事务标记文档/库删除，并写 Audit 和清理 Job；附件删除由附件用例删除关联、mark_deleting、Audit 一起提交。审计失败资源仍可见，不能留下孤立清理任务。</p><p>完整参考：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/deletion.rs" target="_blank" rel="noreferrer">Knowledge 删除用例</a>；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">附件用例</a>。</p><p>自己的读取、搜索、更新、上传完成和导出必须检查删除状态。大集合按批由业务 Handler 清理关联，不在 HTTP 请求遍历全部文件或执行 S3。个人库保留删除标记及唯一关系，首次写入不能自动复活它；旧创建幂等结果也需重新读当前可见性。</p><h2 id="通过公共-files-接口登记清理" tabindex="-1">通过公共 Files 接口登记清理 <a class="header-anchor" href="#通过公共-files-接口登记清理" aria-label="Permalink to &quot;通过公共 Files 接口登记清理&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer">Files 清理</a>公开接口：</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mark_deleting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    connection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;mut</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PgConnection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    correlation_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;(), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span></code></pre></div><p>这是签名摘录，类型 <code>Error</code> 为 Files 错误；在自己的已授权删除事务调用。Core 登记不可变 bucket/key 的 object_cleanup 和任务，不要求自己的 Handler 重写 S3 删除队列。业务关联与文件状态、任务和 Audit 一起提交。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/worker/src/main.rs" target="_blank" rel="noreferrer">Worker 入口</a>注册 <code>files::cleanup_handler</code>、<code>files::rescan_handler</code> 和 <code>files::cleanup_maintenance</code>；自己的业务可另注册关联/过期维护。维护通过 <code>jobs::run_maintenance</code> 独立运行，只做有界数据库/入队，不阻塞续租或做存储 I/O。</p><h2 id="限定工作量并保留位置" tabindex="-1">限定工作量并保留位置 <a class="header-anchor" href="#限定工作量并保留位置" aria-label="Permalink to &quot;限定工作量并保留位置&quot;">​</a></h2><p>每轮最多 100 个目标，事务外 S3 Delete 后以有效租约提交进度；对象已不存在算成功。部分成功后从剩余位置恢复，五次预算耗尽由管理员明确重试，维护不不断补发新预算。清理依据已提交删除状态，不因用户退出停止。</p><p>迟到 PUT/COPY 可能在首次删除后才完成，因此登记位置持续保留。默认一小时后再探测，共享 <code>files.rescan</code> 每轮最多 100 个到期位置；间隔是最早调度，不保证精确完成时间。独立 UUID key 不复用，旧清理不会删除新 ready 文件。</p><p>Core 清理过期 pending/rejected、staging 和非采用候选，不会仅因 retention 过期删除当前 ready 产物。自己的业务应停止到期下载、清快照/引用并调用 mark_deleting，参考导出维护。</p><p>完整参考：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/exports/maintenance.rs" target="_blank" rel="noreferrer">导出维护</a>。</p><h2 id="在途操作与验证" tabindex="-1">在途操作与验证 <a class="header-anchor" href="#在途操作与验证" aria-label="Permalink to &quot;在途操作与验证&quot;">​</a></h2><p>上传完成和导出发布在 I/O 后重新检查资源；复制成功不能复活已删除业务。删除快照中的附件会使未执行导出失败，不能发布缺字节的成功结果。新下载立即拒绝，旧签名 URL 仍有<a href="./attachments">TTL 边界</a>。</p><p>仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deletion</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attachments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span></span></code></pre></div><p>真实 HTTP/Worker 测试验证立即不可见、RustFS 字节删除、Audit 回滚、不复活、复制竞态、过期和晚到对象复查。自己的业务新增删除关联/查询断言，保留 Core 清理能力；接着使用<a href="./export-notifications">通知</a>和<a href="./audit-history">审计</a>追溯结果。</p><p>完整参考：<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/deletion.rs" target="_blank" rel="noreferrer">真实 HTTP/Worker 测试</a>。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/12-deletion-cleanup.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,24)])])}const b=e(n,[["render",l]]);export{c as __pageData,b as default};
